# Coroutines v2 · Phần 3 · FB Tạo flow và vòng đời (Deep Dive: "Flow building" tr. 295–306, "Flow lifecycle functions" tr. 307–317) + sim coroutines.paging.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)
    m = lambda k, vi, en=None: a('m.paging.' + k, vi, en)

    # ---------------- sim coroutines.paging ----------------
    m('title', 'Phân trang: flow (lười) và channelFlow (tải trước)', 'Paging: flow (lazy) versus channelFlow (prefetching)')
    m('overview', 'Mỗi trang có 3 user và tải mất 1 giây; consumer kiểm từng user mất 1 giây và dừng khi gặp User3 (ở trang 2). Chọn builder rồi bấm Step: so thời điểm tìm thấy và số lần gọi mạng.', 'Each page has 3 users and takes 1 second to load; the consumer checks each user for 1 second and stops at User3 (on page 2). Pick a builder and press Step: compare when the user is found and how many network calls are made.')
    m('wrapup', '`flow` lạnh và đồng bộ: trang kế chỉ được tải khi consumer cần tới. Kết quả: xong sau 6 giây, chỉ 2 lần gọi mạng.\n`channelFlow` có một coroutine sản xuất chạy song song: nó tải trang kế trong lúc consumer còn đang kiểm. Kết quả: xong sau 5 giây, nhưng tới 5 lần gọi mạng, có trang tải thừa.\nQuy tắc dễ nhớ: chọn theo thứ bạn cần tiết kiệm; tiết kiệm request thì `flow`, tiết kiệm thời gian thì `channelFlow`.',
      '`flow` is cold and synchronous: the next page loads only when the consumer needs it. Result: done after 6 seconds, with only 2 network calls.\n`channelFlow` has a producer coroutine running in parallel: it loads the next page while the consumer is still checking. Result: done after 5 seconds, but with 5 network calls, some pages loaded for nothing.\nRule of thumb: choose by what you need to save; to save requests use `flow`, to save time use `channelFlow`.')
    m('simp.1', 'Thời gian chỉ để minh hoạ: mỗi lần tải trang hay kiểm user tính tròn 1000 ms. `channelFlow` dùng sức chứa mặc định, nên trong ví dụ này producer không bao giờ phải chờ consumer.',
      'Timings are illustrative only: each page load or user check counts as exactly 1000 ms. `channelFlow` uses the default capacity, so in this example the producer never waits for the consumer.')
    m('ctl.hint', 'Đổi builder và so thời điểm "tìm thấy User3".', 'Switch the builder and compare when "User3 found" happens.')
    m('ctl.mode', 'Builder', 'Builder')
    for k, vi, en in [('flow', 'flow { } (lười)', 'flow { } (lazy)'), ('channelFlow', 'channelFlow { } (tải trước)', 'channelFlow { } (prefetching)')]:
        m('ctl.mode.' + k, vi, en); m('scope.' + k, vi, en)
    m('diagramTitle', 'Tải trang và kiểm user theo thời gian', 'Loading pages and checking users over time')
    m('diagramDesc', 'Hàng producer (tải trang) và hàng consumer (kiểm user)', 'A producer row (loading pages) and a consumer row (checking users)')
    m('n.prod', 'Producer: takePage', 'Producer: takePage')
    m('n.cons', 'Consumer: first { }', 'Consumer: first { }')
    m('axis', 'ms (thời gian của mã) →', 'ms (code time) →')
    m('col', 'Builder', 'Builder')
    m('met.pages', 'Trang đã tải', 'Pages loaded')
    m('met.checked', 'User đã kiểm', 'Users checked')
    m('bar.run', 'đang làm việc (1000 ms)', 'working (1000 ms)')
    m('bar.wait', 'đang chờ', 'waiting')
    m('lbl.page', 'trang {n}', 'page {n}')
    m('lbl.check', 'kiểm User{n}', 'check User{n}')
    m('lbl.waitEmit', 'chờ ở emit', 'waiting at emit')
    m('lbl.waitItem', 'chờ phần tử', 'waiting for an item')
    S = [
        ('fetch', 'Tải trang {page}', 'Load page {page}', 'Producer gọi `takePage({page})`, mất 1 giây; consumer chưa có gì để kiểm.', 'The producer calls `takePage({page})`, taking 1 second; the consumer has nothing to check yet.'),
        ('check', 'Kiểm User{u}', 'Check User{u}', 'Consumer nhận User{u} và kiểm trong 1 giây.', 'The consumer receives User{u} and checks it for 1 second.'),
        ('fetchLazy', 'Hết user: lúc này mới tải trang {page}', 'Out of users: only now load page {page}', 'Với `flow`, builder đang đứng ở `emit` chờ consumer. Chỉ khi consumer xin phần tử kế mà trang cũ đã hết, builder mới chạy tiếp và tải trang mới. Consumer phải chờ cả giây đó.', 'With `flow`, the builder is waiting at `emit` for the consumer. Only when the consumer asks for the next element and the old page is exhausted does the builder continue and load a new page. The consumer waits that whole second.'),
        ('prefetch', 'Song song: tải trang {page}', 'In parallel: load page {page}', 'Với `channelFlow`, producer chạy trong coroutine riêng, gửi user vào channel rồi tải trang tiếp ngay, không chờ consumer.', 'With `channelFlow`, the producer runs in its own coroutine, sends users into the channel and immediately loads the next page, without waiting for the consumer.'),
        ('found', 'Tìm thấy User3', 'User3 found', '`first` có kết quả và hủy flow: producer bị hủy (với channelFlow, việc tải dở cũng bị hủy).', '`first` has its result and cancels the flow: the producer is cancelled (with channelFlow, the in-flight load is cancelled too).'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('lazy', 'Lười = không tải thừa, nhưng consumer phải chờ mỗi lần sang trang.', 'Lazy = no wasted loads, but the consumer waits at every page boundary.'),
        ('prefetch', 'Độc lập giữa sản xuất và tiêu thụ là tính chất của nguồn NÓNG; channelFlow là lai giữa Channel và Flow.', 'Independent production and consumption is a property of HOT sources; channelFlow is a Channel–Flow hybrid.'),
        ('foundFlow', 'Xong sau 6 giây với 2 lần gọi mạng.', 'Done after 6 seconds with 2 network calls.'),
        ('foundCh', 'Xong sau 5 giây, nhưng đã gọi mạng 5 lần; các trang 2–4 tải thừa. Nhanh hơn có giá.', 'Done after 5 seconds, but with 5 network calls; pages 2–4 were loaded for nothing. Speed has a price.')]:
        m('co.' + k, vi, en)
    a('cap.paging', 'Hai hàng theo thời gian của mã: producer tải trang (mỗi thanh 1 giây) và consumer kiểm user (mỗi thanh 1 giây). Thanh viền đứt = đang chờ. Đổi builder và so điểm kết thúc (mốc User3) và số thanh "trang".', 'Two rows over code time: the producer loading pages (each bar 1 second) and the consumer checking users (each bar 1 second). A dashed bar = waiting. Switch the builder and compare the end point (the User3 marker) and the number of "page" bars.')

    # ---------------- chương FB ----------------
    C = 'fb'
    a(C + '.title', 'Tạo flow và vòng đời: flowOf, flow, channelFlow, callbackFlow, onStart, catch, flowOn', 'Building flows and their lifecycle: flowOf, flow, channelFlow, callbackFlow, onStart, catch, flowOn')
    a(C + '.essence',
      'Một flow bắt đầu từ đâu? Từ giá trị có sẵn (`flowOf`, `emptyFlow`), từ phép chuyển đổi (`asFlow` từ collection, sequence, hàm suspend, Reactive Streams), hoặc từ builder.\n`flow { emit(…) }` là builder cơ bản: lười và đồng bộ. `channelFlow { send(…) }` là con lai giữa Channel và Flow: vẫn là Flow (chỉ chạy khi có người collect), nhưng sản xuất trong một coroutine riêng, nên chạy song song với consumer và được `launch` bên trong. `callbackFlow` dùng để bọc API kiểu callback: đăng ký listener, gửi bằng `trySendBlocking`, và BẮT BUỘC có `awaitClose { gỡ listener }`.\nHình dung flow như một đường ống: yêu cầu đi ngược lên nguồn, giá trị chảy xuống. Khi xong hay có lỗi, tin đó cũng chảy xuống và đóng từng đoạn ống. Ta gắn "cảm biến" vào các sự kiện ấy: `onEach`, `onStart` (khi bắt đầu collect), `onCompletion` (xong, lỗi hay bị hủy), `onEmpty`, `catch` (chỉ bắt lỗi PHÍA TRÊN nó).\nContext của mọi lambda trong flow lấy từ nơi gọi `collect`. `flowOn(ctx)` đổi context cho các đoạn PHÍA TRÊN nó. `launchIn(scope)` collect trong một coroutine mới. Mẫu hay gặp trên Android: `onStart { hiện } .onCompletion { ẩn } .onEach { vẽ } .catch { báo lỗi } .launchIn(viewModelScope)`.\nQuy tắc dễ nhớ: trong chuỗi flow, mọi thứ "nhìn lên trên": `catch` bắt lỗi phía trên, `flowOn` đổi context phía trên.',
      'Where does a flow start? From ready values (`flowOf`, `emptyFlow`), from conversions (`asFlow` from collections, sequences, suspending functions, Reactive Streams), or from builders.\n`flow { emit(…) }` is the basic builder: lazy and synchronous. `channelFlow { send(…) }` is a Channel–Flow hybrid: still a Flow (it only runs when someone collects), but it produces in a separate coroutine, so it runs in parallel with the consumer and can `launch` inside. `callbackFlow` wraps callback-style APIs: register a listener, send with `trySendBlocking`, and you MUST have `awaitClose { remove the listener }`.\nPicture a flow as a pipe: requests travel up to the source, values flow down. When it finishes or fails, that news also flows down and closes each section of pipe. We attach "sensors" to those events: `onEach`, `onStart` (when collection begins), `onCompletion` (done, failed or cancelled), `onEmpty`, `catch` (catches errors ABOVE it only).\nThe context of every lambda in a flow comes from where `collect` is called. `flowOn(ctx)` changes the context for the sections ABOVE it. `launchIn(scope)` collects in a new coroutine. A common Android pattern: `onStart { show } .onCompletion { hide } .onEach { render } .catch { report } .launchIn(viewModelScope)`.\nRule of thumb: in a flow chain everything "looks upward": `catch` catches errors above, `flowOn` changes the context above.')
    a(C + '.goal.g1', 'Đã thấy flow lười chờ tới lúc cần mới tải trang', 'Saw the lazy flow wait until needed before loading a page')
    a(C + '.goal.g2', 'Đã so flow và channelFlow tới cuối', 'Compared flow and channelFlow to the end')

    S = 'recap'
    a(C + '.sec.%s.title' % S, 'Ôn nhanh chương trước', 'Quick review of the previous chapter')
    B(C, S, 1, 'ask', '`emit` trong `flow { }` làm gì? Vì sao một phần tử phải xử lý xong thì phần tử sau mới được tạo?', 'What does `emit` in `flow { }` do? Why must one element be fully handled before the next is created?')
    B(C, S, 1, 'ans', '`emit` gọi thẳng lambda của tầng dưới (tới `collect`), và chỉ trả về khi lambda đó xong. Builder đứng ở `emit` suốt lúc đó: flow đồng bộ. Chương này thêm những builder phá vỡ tính đồng bộ đó một cách có chủ ý (`channelFlow`, `callbackFlow`).', '`emit` calls the downstream lambda directly (down to `collect`), and returns only when that lambda is done. The builder stays at `emit` the whole time: flow is synchronous. This chapter adds builders that deliberately break that synchrony (`channelFlow`, `callbackFlow`).')

    S = 'raw'
    a(C + '.sec.%s.title' % S, 'Từ giá trị có sẵn và chuyển đổi', 'From ready values and conversions')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'kt', 'flowOf(1, 2, 3, 4, 5).collect { print(it) }      // 12345\nemptyFlow<Int>().collect { print(it) }           // (không gì)\nlistOf(1, 2, 3).asFlow()                         // Iterable, Iterator, Sequence → Flow\n\nsuspend fun getUserName(): String { delay(1000); return "UserName" }\n::getUserName.asFlow().collect { println(it) }   // (1 s) UserName\nsuspend { delay(1000); "UserName" }.asFlow()      // lambda suspend → Flow một phần tử\n\n// Reactive Streams (kotlinx-coroutines-reactive / -rx3 / -reactor)\nFlowable.range(1, 5).asFlow()                    // Publisher → Flow\nflowOf(1, 2, 3).asFlowable()                     // Flow → Flowable', 'flowOf(1, 2, 3, 4, 5).collect { print(it) }      // 12345\nemptyFlow<Int>().collect { print(it) }           // (nothing)\nlistOf(1, 2, 3).asFlow()                         // Iterable, Iterator, Sequence → Flow\n\nsuspend fun getUserName(): String { delay(1000); return "UserName" }\n::getUserName.asFlow().collect { println(it) }   // (1 s) UserName\nsuspend { delay(1000); "UserName" }.asFlow()      // a suspending lambda → a one-element Flow\n\n// Reactive Streams (kotlinx-coroutines-reactive / -rx3 / -reactor)\nFlowable.range(1, 5).asFlow()                    // Publisher → Flow\nflowOf(1, 2, 3).asFlowable()                     // Flow → Flowable')
    B(C, S, 2, 'p', 'Flow hay được dùng để biểu diễn một giá trị đến sau, giống `Single` của RxJava. Vì thế mới có `asFlow` cho kiểu hàm: một hàm suspend trở thành flow có đúng một phần tử.\nNếu dự án đang dùng RxJava hay Reactor thì không cần viết lại lớn. Mọi `Flux`, `Flowable`, `Observable` đều hiện thực `Publisher`, và chuyển sang Flow được bằng `asFlow`. Chiều ngược lại cần thư viện riêng (`-reactor`, `-rx2`, `-rx3`).\nQuy tắc dễ nhớ: có sẵn dữ liệu ở dạng nào thì thường đã có một `asFlow` cho dạng đó.',
      "Flow is often used to represent one value that arrives later, like RxJava's `Single`. That is why there is `asFlow` for function types: a suspending function becomes a flow with exactly one element.\nIf a project already uses RxJava or Reactor, no big rewrite is needed. Every `Flux`, `Flowable` and `Observable` implements `Publisher`, and converts to Flow with `asFlow`. The other direction needs specific libraries (`-reactor`, `-rx2`, `-rx3`).\nRule of thumb: whatever form your data already has, there is usually an `asFlow` for it.")

    S = 'builders'
    a(C + '.sec.%s.title' % S, 'flow { } và channelFlow { }: lười và tải trước', 'flow { } and channelFlow { }: lazy and prefetching')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`flow { }` là builder cơ bản; mọi builder khác dựa trên nó (FL "Flow từ gốc" đã tự dựng lại nó từ một lambda). Bên trong dùng `emit(value)`, hoặc `emitAll(flow)`, viết tắt của `flow.collect { emit(it) }`.\nGọi builder chỉ tạo ra một đối tượng. Gọi `collect` mới chạy khối của builder, và mỗi `emit` gọi thẳng lambda của `collect`. Flow lạnh, nên trang kế chỉ được tải khi người nhận cần tới.\nMuốn tải trước trang kế trong lúc đang xử lý trang này, thì việc sản xuất và việc tiêu thụ phải ĐỘC LẬP với nhau. Đó là tính chất của nguồn nóng. `channelFlow { }` là con lai: nó hiện thực `Flow` (chỉ khởi động khi có thao tác cuối), nhưng khi đã chạy thì sản xuất trong một coroutine riêng, không chờ người nhận ([[src:kx-channelflow]]).\nQuy tắc dễ nhớ: `flow` làm theo đơn đặt hàng; `channelFlow` làm sẵn trong lúc khách còn đang ăn.',
      '`flow { }` is the basic builder; every other builder rests on it (FL "Flow from the ground up" rebuilt it from a lambda). Inside you use `emit(value)`, or `emitAll(flow)`, short for `flow.collect { emit(it) }`.\nCalling the builder only creates an object. Calling `collect` runs the builder block, and each `emit` calls straight into the `collect` lambda. A flow is cold, so the next page is loaded only when the receiver needs it.\nTo load the next page ahead while still processing this one, production and consumption must be INDEPENDENT of each other. That is a property of hot sources. `channelFlow { }` is a hybrid: it implements `Flow` (starting only with a final operation), but once running it produces in a separate coroutine, without waiting for the receiver ([[src:kx-channelflow]]).\nRule of thumb: `flow` cooks to order; `channelFlow` cooks ahead while the customer is still eating.')
    B(C, S, 2, 'predict', 'Mỗi trang 3 user, tải 1 giây; kiểm mỗi user 1 giây; `first { it.name == "User3" }`. Với `flow`, tìm thấy sau bao lâu và gọi mạng mấy lần? Với `channelFlow`?', 'Each page has 3 users and takes 1 second to load; checking each user takes 1 second; `first { it.name == "User3" }`. With `flow`, how long until found, and how many network calls? With `channelFlow`?')
    B(C, S, 2, 'ans', '`flow`: 6 giây (tải trang 0, kiểm 3 user, tải trang 1, kiểm User3), 2 lần gọi. `channelFlow`: 5 giây (trang kế tải song song với việc kiểm), nhưng 5 lần gọi mạng, trong đó các trang 2–4 thừa. Bấm Step trong mô phỏng ngay dưới để so.', '`flow`: 6 seconds (load page 0, check 3 users, load page 1, check User3), 2 calls. `channelFlow`: 5 seconds (the next page loads in parallel with checking), but 5 network calls, pages 2–4 wasted. Step through the simulation just below to compare.')
    B(C, S, 3, 'p', 'Trong `channelFlow`, ta làm việc trên một `ProducerScope<T>`, cùng kiểu với `produce`. Nó là một `CoroutineScope`, nên gọi `launch` trực tiếp được. Phần tử được gửi bằng `send`, không phải `emit`. `channelFlow` chỉ xong khi mọi con của nó xong.\nHai ví dụ hữu ích: gộp hai flow làm một (`launch { collect { send(it) } }; other.collect { send(it) }`), hoặc tính giá trị trên các dispatcher khác nhau rồi gửi về một chỗ.',
      'Inside `channelFlow`, we work on a `ProducerScope<T>`, the same type `produce` uses. It is a `CoroutineScope`, so you can call `launch` directly. Elements are sent with `send`, not `emit`. `channelFlow` finishes only when all its children finish.\nTwo useful examples: merging two flows into one (`launch { collect { send(it) } }; other.collect { send(it) }`), or computing values on different dispatchers and sending them back to one place.')

    S = 'callback'
    a(C + '.sec.%s.title' % S, 'callbackFlow: bọc API callback (listener, sensor, click)', 'callbackFlow: wrapping callback APIs (listeners, sensors, clicks)')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Nhiều nguồn sự kiện chỉ có dạng callback: bấm nút, vị trí, cảm biến, listener của một SDK. Việc nghe các sự kiện này phải độc lập với việc xử lý chúng. Đó là chỗ của `callbackFlow`.\nNó cũng làm việc trên một `ProducerScope`, với bốn công cụ ([[src:kx-callbackflow]]):\n• `awaitClose { … }`: tạm dừng tới khi channel đóng, rồi chạy khối dọn dẹp.\n• `trySendBlocking(value)`: gửi từ một hàm không phải suspend, như bên trong callback.\n• `close()`: kết thúc flow.\n• `cancel(throwable)`: kết thúc flow và đưa một exception vào flow.\nQuy tắc dễ nhớ: listener đăng ký ở đâu thì gỡ trong `awaitClose` ở đó.',
      "Many event sources only come as callbacks: button taps, location, sensors, an SDK's listener. Listening to these events must be independent of handling them. That is where `callbackFlow` fits.\nIt also works on a `ProducerScope`, with four tools ([[src:kx-callbackflow]]):\n• `awaitClose { … }`: pauses until the channel closes, then runs the cleanup block.\n• `trySendBlocking(value)`: sends from a function that is not suspending, such as inside a callback.\n• `close()`: ends the flow.\n• `cancel(throwable)`: ends the flow and sends an exception into it.\nRule of thumb: wherever you register a listener, remove it in `awaitClose` right there.")
    B(C, S, 2, 'kt', 'fun locationUpdates(client: LocationClient): Flow<Location> = callbackFlow {\n    val callback = object : LocationCallback {\n        override fun onLocation(l: Location) { trySendBlocking(l) }\n        override fun onError(e: Throwable) { cancel(CancellationException("Location error", e)) }\n        override fun onDone() { channel.close() }\n    }\n    client.register(callback)\n    awaitClose { client.unregister(callback) }   // BẮT BUỘC: giữ flow sống và gỡ listener khi ngừng collect\n}', 'fun locationUpdates(client: LocationClient): Flow<Location> = callbackFlow {\n    val callback = object : LocationCallback {\n        override fun onLocation(l: Location) { trySendBlocking(l) }\n        override fun onError(e: Throwable) { cancel(CancellationException("Location error", e)) }\n        override fun onDone() { channel.close() }\n    }\n    client.register(callback)\n    awaitClose { client.unregister(callback) }   // REQUIRED: keeps the flow alive and removes the listener when collection stops\n}')
    B(C, S, 3, 'ask', 'Vì sao thiếu `awaitClose` thì flow kết thúc ngay sau khi đăng ký listener?', 'Why does the flow end right after registering the listener when `awaitClose` is missing?')
    B(C, S, 3, 'ans', 'Vì thân coroutine của builder đã chạy hết và không có con nào để chờ, nên coroutine kết thúc, đóng channel và không nhận được sự kiện nào nữa. Thư viện coi đây là lỗi lập trình và báo exception. `awaitClose` giữ coroutine sống tới khi channel đóng (người collect hủy, hoặc `close()`), rồi chạy khối gỡ listener.', 'Because the builder\'s coroutine body has run to the end with no children to wait for, so the coroutine ends, closes the channel, and no more events arrive. The library treats this as a programming error and throws. `awaitClose` keeps the coroutine alive until the channel closes (the collector cancels, or `close()` is called), then runs the block that removes the listener.')

    S = 'lifecycle'
    a(C + '.sec.%s.title' % S, 'Vòng đời: onEach, onStart, onCompletion, onEmpty', 'The lifecycle: onEach, onStart, onCompletion, onEmpty')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'note', 'Hình dung flow như một đường ống hai chiều. Yêu cầu "cho tôi phần tử kế" đi ngược lên nguồn; giá trị chảy xuống người collect. Khi flow xong hay có exception, tin đó cũng chảy xuống và đóng từng đoạn ống trên đường. Các hàm vòng đời là những "cảm biến" gắn vào ống.\nChỗ khớp: gắn cảm biến theo thứ tự nào trong chuỗi thì sự kiện đi qua theo đúng thứ tự đó. Chỗ không khớp: ống không có nước chảy sẵn. Không có ai collect thì ống trống rỗng (flow lạnh).',
      'Picture a flow as a two-way pipe. "Give me the next element" requests travel up to the source; values flow down to the collector. When the flow finishes or throws, that news also flows down and closes each section of pipe on the way. Lifecycle functions are "sensors" attached to the pipe.\nWhere it fits: whatever order you attach the sensors in the chain is the order events pass through them. Where it does not: no water flows by itself. With no collector, the pipe is empty (the flow is cold).')
    B(C, S, 1, 'kind', 'analogy')
    B(C, S, 2, 'kt', 'flowOf(1, 2)\n    .onEach { delay(1000) }           // trễ mỗi phần tử (tuần tự)\n    .onStart { emit(0) }              // chạy khi collect bắt đầu, KHÔNG chờ phần tử đầu; được emit\n    .onCompletion { println("Completed") }   // xong, lỗi HOẶC bị hủy đều gọi\n    .collect { println(it) }\n// 0 / (1 s) 1 / (1 s) 2 / Completed\n\nflow<List<Int>> { delay(1000) }\n    .onEmpty { emit(emptyList()) }    // xong mà không emit gì → phát giá trị mặc định\n    .collect { println(it) }          // (1 s) []', 'flowOf(1, 2)\n    .onEach { delay(1000) }           // delays each element (sequentially)\n    .onStart { emit(0) }              // runs when collection starts, NOT waiting for the first element; may emit\n    .onCompletion { println("Completed") }   // called on completion, failure OR cancellation\n    .collect { println(it) }\n// 0 / (1 s) 1 / (1 s) 2 / Completed\n\nflow<List<Int>> { delay(1000) }\n    .onEmpty { emit(emptyList()) }    // completed without emitting → emit a default\n    .collect { println(it) }          // (1 s) []')
    B(C, S, 3, 'predict', 'Collect `flowOf(1, 2).onEach { delay(1000) }.onCompletion { println("Completed") }.collect { println(it) }` trong một `launch`, rồi hủy job sau 1100 ms. In gì?', 'Collect `flowOf(1, 2).onEach { delay(1000) }.onCompletion { println("Completed") }.collect { println(it) }` inside a `launch`, then cancel the job after 1100 ms. What is printed?')
    B(C, S, 3, 'ans', '"1" (ở 1 giây) rồi "Completed" (ở 1,1 giây). `onCompletion` cũng chạy khi bị hủy, nên trên Android dùng `onStart` để hiện progress và `onCompletion` để ẩn nó (ẩn cả khi lỗi hay rời màn hình).', '"1" (at 1 second), then "Completed" (at 1.1 seconds). `onCompletion` also runs on cancellation, which is why Android code uses `onStart` to show progress and `onCompletion` to hide it (hidden even on errors or when leaving the screen).')

    S = 'catch'
    a(C + '.sec.%s.title' % S, 'catch: chỉ bắt lỗi phía trên nó', 'catch: only catches errors above it')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Một exception xảy ra ở bất kỳ đâu khi tạo hay xử lý flow sẽ chảy xuống dưới, đóng từng đoạn ống trên đường. `onEach`, `map`, `filter` không phản ứng gì với exception; chỉ `onCompletion` được gọi.\n`catch { e -> … }` bắt exception đó, và có thể phát một giá trị thay thế để phần còn lại của flow sống tiếp. Nhưng nó chỉ bắt lỗi từ các đoạn PHÍA TRÊN nó. Lỗi ở phía dưới, kể cả trong `collect`, nó không thấy.\nException không ai bắt sẽ hủy flow ngay, và `collect` ném lại nó. Vì vậy bọc `try/catch` quanh `collect` cũng được.\nQuy tắc dễ nhớ: muốn `catch` bảo vệ đoạn mã nào thì đặt đoạn đó PHÍA TRÊN `catch`, ví dụ dời việc hiển thị vào `onEach`.',
      'An exception that happens anywhere while building or processing a flow flows downward, closing each section of pipe on the way. `onEach`, `map`, `filter` do not react to exceptions at all; only `onCompletion` is called.\n`catch { e -> … }` catches that exception, and can emit a fallback value so the rest of the flow stays alive. But it only catches errors from the sections ABOVE it. Errors below it, including inside `collect`, it never sees.\nAn exception nobody catches cancels the flow at once, and `collect` rethrows it. So a `try/catch` around `collect` works too.\nRule of thumb: to have `catch` protect some code, put that code ABOVE the `catch`, for example by moving the rendering into `onEach`.')
    B(C, S, 2, 'kt', 'val flow = flow { emit(1); emit(2); throw MyError() }\nflow.onEach { println("Got $it") }\n    .catch { println("Caught $it"); emit(-1) }\n    .collect { println("Collected $it") }\n// Got 1 / Collected 1 / Got 2 / Collected 2 / Caught MyError / Collected -1\n\n// catch KHÔNG bắt lỗi trong collect (nó nằm dưới catch):\nflow.catch { … }.collect { throw MyError() }     // lỗi thoát ra ngoài\n// → dời thao tác vào onEach đặt TRƯỚC catch:\nflow.onEach { render(it) }.catch { showError(it) }.collect()', 'val flow = flow { emit(1); emit(2); throw MyError() }\nflow.onEach { println("Got $it") }\n    .catch { println("Caught $it"); emit(-1) }\n    .collect { println("Collected $it") }\n// Got 1 / Collected 1 / Got 2 / Collected 2 / Caught MyError / Collected -1\n\n// catch does NOT catch errors in collect (it sits below catch):\nflow.catch { … }.collect { throw MyError() }     // the error escapes\n// → move the work into onEach placed BEFORE catch:\nflow.onEach { render(it) }.catch { showError(it) }.collect()')

    S = 'flowon'
    a(C + '.sec.%s.title' % S, 'flowOn và launchIn: context đến từ đâu', 'flowOn and launchIn: where the context comes from')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Mọi lambda của builder và toán tử đều là hàm suspend, nên đều cần một context. Context đó lấy từ nơi gọi `collect`: thao tác cuối xin phần tử từ phía trên, và mang context của nó theo lên.\n`flowOn(ctx)` đổi context cho các đoạn PHÍA TRÊN nó, thường để builder chạy trên `Dispatchers.IO`. Các đoạn phía dưới vẫn giữ context của người collect ([[src:kx-flowon]]).\n`launchIn(scope)` chỉ là `scope.launch { collect() }`: chạy việc collect trong một coroutine mới, để nơi gọi không phải chờ.\nQuy tắc dễ nhớ: đặt `flowOn` ngay dưới phần việc nặng, và đừng bao giờ dùng `withContext` để đổi luồng bên trong `flow { }`.',
      "Every builder and operator lambda is a suspending function, so each needs a context. That context comes from where `collect` is called: the final operation asks upstream for elements, and carries its context up with it.\n`flowOn(ctx)` changes the context for the sections ABOVE it, typically so the builder runs on `Dispatchers.IO`. The sections below keep the collector's context ([[src:kx-flowon]]).\n`launchIn(scope)` is just `scope.launch { collect() }`: it collects in a new coroutine, so the caller does not have to wait.\nRule of thumb: put `flowOn` right below the heavy work, and never use `withContext` to switch threads inside `flow { }`.")
    B(C, S, 2, 'kt', 'withContext(CoroutineName("Name1")) {\n    messagesFlow()                              // builder chạy ở Name3\n        .flowOn(CoroutineName("Name3"))\n        .onEach { present("onEach", it) }       // Name2\n        .flowOn(CoroutineName("Name2"))\n        .collect { present("collect", it) }    // Name1\n}\n\n// mẫu Android\nfun updateNews() {\n    newsFlow()\n        .onStart { showProgressBar() }\n        .onCompletion { hideProgressBar() }\n        .onEach { view.showNews(it) }\n        .catch { view.handleError(it) }\n        .launchIn(viewModelScope)\n}', 'withContext(CoroutineName("Name1")) {\n    messagesFlow()                              // the builder runs in Name3\n        .flowOn(CoroutineName("Name3"))\n        .onEach { present("onEach", it) }       // Name2\n        .flowOn(CoroutineName("Name2"))\n        .collect { present("collect", it) }    // Name1\n}\n\n// the Android pattern\nfun updateNews() {\n    newsFlow()\n        .onStart { showProgressBar() }\n        .onCompletion { hideProgressBar() }\n        .onEach { view.showNews(it) }\n        .catch { view.handleError(it) }\n        .launchIn(viewModelScope)\n}')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp khi tạo và xử lý vòng đời flow', 'Common bugs when building flows and handling their lifecycle')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Bạn viết `flow { withContext(Dispatchers.IO) { emit(db.read()) } }` và app crash: IllegalStateException về "Flow invariant is violated", phát giá trị từ context khác.', 'You write `flow { withContext(Dispatchers.IO) { emit(db.read()) } }` and the app crashes: an IllegalStateException about "Flow invariant is violated", emitting from a different context.')
    B(C, S, 1, 'cause', '`flow { }` đồng bộ và chạy trong context của người collect; `emit` gọi thẳng lambda của người collect. Gọi `emit` từ context khác sẽ chạy mã của người collect sai context, nên thư viện cấm (lớp `SafeCollector` kiểm tra điều này).', '`flow { }` is synchronous and runs in the collector\'s context; `emit` calls the collector\'s lambda directly. Emitting from another context would run the collector\'s code in the wrong context, so the library forbids it (the `SafeCollector` layer checks this).')
    B(C, S, 1, 'fix', 'Dùng `flowOn(Dispatchers.IO)` sau builder. Hoặc chỉ bọc phần đọc: `val data = withContext(IO) { db.read() }; emit(data)`. Nếu thật sự cần phát từ nhiều coroutine/context, dùng `channelFlow`.', 'Use `flowOn(Dispatchers.IO)` after the builder. Or wrap only the read: `val data = withContext(IO) { db.read() }; emit(data)`. If you really must emit from several coroutines/contexts, use `channelFlow`.')
    B(C, S, 2, 'bug', 'Màn hình bản đồ: sau khi rời màn hình, GPS vẫn bật và pin tụt nhanh.', 'A map screen: after leaving it, GPS stays on and the battery drains fast.')
    B(C, S, 2, 'cause', '`callbackFlow` đăng ký listener nhưng `awaitClose { }` để trống (hoặc không gỡ listener ở đó). Người collect đã hủy nhưng listener vẫn còn trong SDK.', 'The `callbackFlow` registers a listener but leaves `awaitClose { }` empty (or does not remove the listener there). The collector has cancelled, but the listener is still registered with the SDK.')
    B(C, S, 2, 'fix', 'Luôn gỡ listener trong `awaitClose { client.unregister(callback) }`, và collect bằng scope có vòng đời (`repeatOnLifecycle`, `viewModelScope`).', 'Always remove the listener in `awaitClose { client.unregister(callback) }`, and collect with a lifecycle-aware scope (`repeatOnLifecycle`, `viewModelScope`).')
    B(C, S, 3, 'bug', 'Bạn có `newsFlow().catch { showError(it) }.map { parse(it) }.collect { render(it) }`. Lỗi parse vẫn làm crash app.', 'You have `newsFlow().catch { showError(it) }.map { parse(it) }.collect { render(it) }`. A parse error still crashes the app.')
    B(C, S, 3, 'cause', '`catch` chỉ bắt lỗi phía TRÊN nó. `map` và `collect` nằm phía dưới nên lỗi của chúng thoát ra.', '`catch` only catches errors ABOVE it. `map` and `collect` sit below it, so their errors escape.')
    B(C, S, 3, 'fix', 'Đặt `catch` sau mọi toán tử có thể lỗi, dời việc render vào `onEach` trước `catch`, và kết thúc bằng `collect()`/`launchIn`.', 'Place `catch` after every operator that may fail, move rendering into `onEach` before `catch`, and finish with `collect()`/`launchIn`.')
    B(C, S, 3, 'fixkt', 'newsFlow()\n    .map { parse(it) }\n    .onEach { render(it) }\n    .catch { showError(it) }\n    .launchIn(viewModelScope)')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Đoán output:', 'Predict the output:')
    B(C, S, 1, 'exkt', 'flow { emit("A"); throw IOException() }\n    .onStart { println("start") }\n    .onEach { println("each $it") }\n    .onCompletion { e -> println("done ${e != null}") }\n    .catch { println("caught"); emit("fallback") }\n    .collect { println("got $it") }')
    B(C, S, 1, 'sol', 'start → each A → got A → done true → caught → got fallback. `onCompletion` nằm trên `catch` nên thấy lỗi (e != null); `catch` bắt lỗi, phát "fallback" xuống `collect`.', 'start → each A → got A → done true → caught → got fallback. `onCompletion` is above `catch`, so it sees the error (e != null); `catch` catches it and emits "fallback" down to `collect`.')
    B(C, S, 2, 'ex', 'Bài khuyết bước: viết `fun EditText.textChanges(): Flow<String>` bằng `callbackFlow`, gỡ `TextWatcher` khi ngừng collect.', 'A partly-solved exercise: write `fun EditText.textChanges(): Flow<String>` with `callbackFlow`, removing the `TextWatcher` when collection stops.')
    B(C, S, 2, 'hint', 'Ba phần: tạo watcher gọi `trySend`, `addTextChangedListener`, `awaitClose { removeTextChangedListener }`.', 'Three parts: a watcher that calls `trySend`, `addTextChangedListener`, `awaitClose { removeTextChangedListener }`.')
    B(C, S, 2, 'sol', 'Callback của `TextWatcher` chạy trên luồng Main và không suspend, nên dùng `trySend` (hoặc `trySendBlocking`). `awaitClose` vừa giữ flow sống, vừa gỡ watcher.', 'The `TextWatcher` callback runs on the Main thread and does not suspend, so use `trySend` (or `trySendBlocking`). `awaitClose` both keeps the flow alive and removes the watcher.')
    B(C, S, 2, 'solkt', 'fun EditText.textChanges(): Flow<String> = callbackFlow {\n    val watcher = doAfterTextChanged { trySend(it?.toString().orEmpty()) }\n    awaitClose { removeTextChangedListener(watcher) }\n}')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Khi nào dùng `flow`, `channelFlow`, `callbackFlow`?', 'When do you use `flow`, `channelFlow`, `callbackFlow`?')
    B(C, S, 1, 'ans', '`flow`: mặc định, lười, đồng bộ, theo yêu cầu. `channelFlow`: cần sản xuất độc lập hoặc song song (tải trước, gộp flow, nhiều coroutine gửi). `callbackFlow`: bọc API callback/listener, bắt buộc `awaitClose`.', '`flow`: the default, lazy, synchronous, on demand. `channelFlow`: when production must be independent or parallel (prefetching, merging flows, several coroutines sending). `callbackFlow`: wrapping callback/listener APIs, with a mandatory `awaitClose`.')
    B(C, S, 2, 'ask', '`catch` và `flowOn` cùng có tính chất "phía trên". Phát biểu quy tắc đó.', '`catch` and `flowOn` share an "upstream" property. State the rule.')
    B(C, S, 2, 'ans', 'Cả hai chỉ tác động lên các tầng nằm PHÍA TRÊN chúng trong chuỗi: `catch` chỉ bắt lỗi từ phía trên; `flowOn` chỉ đổi context cho phía trên. Phía dưới giữ nguyên.', 'Both affect only the stages ABOVE them in the chain: `catch` only catches errors from above; `flowOn` only changes the context of what is above. Everything below stays as it was.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', '`onStart` chạy lúc nào?', 'When does `onStart` run?',
         'Ngay khi thao tác terminal bắt đầu (khi xin phần tử đầu), không chờ phần tử đầu tới.', 'As soon as the terminal operation starts (when the first element is requested), without waiting for it to arrive.', 'Có thể emit trong `onStart`.', 'You can emit inside `onStart`.'),
        ('q2', '`onCompletion` có được gọi khi coroutine collect bị hủy không?', 'Is `onCompletion` called when the collecting coroutine is cancelled?',
         'Có.', 'Yes.', 'Nó chạy khi xong, khi lỗi và khi bị hủy.', 'It runs on completion, on failure and on cancellation.'),
        ('q3', 'Builder nào cho phép `launch` trực tiếp bên trong?', 'Which builder lets you `launch` directly inside it?',
         '`channelFlow` (và `callbackFlow`).', '`channelFlow` (and `callbackFlow`).', 'Chúng chạy trên `ProducerScope`, một `CoroutineScope`; `flow { }` không có scope.', 'They run on a `ProducerScope`, which is a `CoroutineScope`; `flow { }` has no scope.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
